create schema app;
create table app.orders (id int primary key, amount numeric not null, status text not null);
create materialized view app.totals as select status, sum(amount) as total from app.orders group by status;
create unique index totals_status on app.totals (status);
comment on materialized view app.totals is 'totals per status';
comment on column app.totals.total is 'sum of amounts';
comment on index app.totals_status is 'one row per status';
create index orders_amount on app.orders (amount);
comment on index app.orders_amount is 'for range scans';
alter table app.orders add constraint amount_positive check (amount > 0);
comment on constraint amount_positive on app.orders is 'no free orders';
create domain app.code as text constraint code_short check (length(value) < 10);
comment on constraint code_short on domain app.code is 'codes are short';
create function app.touch() returns trigger language plpgsql as $body$ begin return new; end $body$;
create constraint trigger orders_touch after insert on app.orders for each row execute function app.touch();
comment on trigger orders_touch on app.orders is 'checks inserts';
alter table app.orders enable row level security;
create policy open_orders on app.orders using (status = 'open');
comment on policy open_orders on app.orders is 'only open orders';
